func:
var instructionMsg = '**CRITICAL**: Please review task ' + msg.task.id + ' and provide your feedback using the `build review` command.\n\n' +
    'The syntax is:\n' +
    'build review ' + msg.task.id + ' <approve|reject> "<reasoning>"\n\n' +
    'RULES:\n' +
    '1. Your reasoning MUST be a single line of text.\n' +
    '2. Enclose your reasoning in double quotes (").\n' +
    '3. DO NOT use double quotes inside your reasoning string (use single quotes instead).\n' +
    '4. DO NOT ask questions; provide ONLY the final review via the bash tool.';

msg.payload = "sqlite3 .build/build.db \"INSERT INTO comments (task_id, agent_id, content) VALUES ('" + msg.task.id + "', 1, '" + instructionMsg.replace(/'/g, "''") + "'); UPDATE tasks SET agent_id = 4 WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'assign_to_boss', '" + msg.adapter + "', '', 'build');\"";
return msg;

var errorMsg = 'Tests failed:\n' + msg.payload;
// Fetch current approval attempts via subquery or just perform update with attempts incremented
msg.payload = "sqlite3 .build/build.db \"INSERT INTO comments (task_id, agent_id, content) VALUES ('" + msg.task.id + "', 3, '" + errorMsg.replace(/'/g, "''") + "'); UPDATE tasks SET approval_attempts = approval_attempts + 1 WHERE id = '" + msg.task.id + "';\" && " +
    "sqlite3 -json .build/build.db \"SELECT approval_attempts, lead_interventions FROM tasks WHERE id = '" + msg.task.id + "'\"";
return msg;

var stdout = (msg.payload || '').trim();
try {
    var res = JSON.parse(stdout);
    var attempts = res[0].approval_attempts;
    var lead_interventions = res[0].lead_interventions;

    if (attempts >= 3) {
        if (lead_interventions < 3) {
            msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET status = 'stuck', agent_id = 5, approval_attempts = 0, lead_interventions = lead_interventions + 1 WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'escalate_to_lead', '" + msg.adapter + "', '', 'build');\"";
        } else {
            msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET status = 'failed', agent_id = 1, approval_attempts = '" + attempts + "' WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'task_rejected', '" + msg.adapter + "', '', 'build');\"";
        }
    } else {
        msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET agent_id = 2 WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'assign_to_dev', '" + msg.adapter + "', '', 'build');\"";
    }
} catch (e) {
    node.error('Error parsing attempts JSON: ' + e.message);
    // Fallback to dev
    msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET agent_id = 2 WHERE id = '" + msg.task.id + "';\"";
}
return msg;
